// The C side of the astro backend: ASTro's sample/luastro (a Lua 5.4 subset; an AST interpreter whose nodes are defined in
// node.def and generated by ASTroGen) as a library. See nfcpoly_astro_shim.h, docs/notes/poly.md and docs/notes/astro.md.
//
// luastro has no embedding API: its main.c #includes the tokenizer, parser, runtime and standard library (they share static
// state) and drives them from a command line. This file is that main.c without the command line: the same declarations and
// includes, then the entry points of nfcpoly_astro_shim.h. scripts/setup-poly-astro.sh compiles it with -I at a patched copy
// of the luastro directory (the evaluator is generated there) and archives it with node.c as libluastro.a. Nothing of luastro
// is edited; the code store (SD_* specialization, dlopen of all.so) is off (OPTION.no_compiled_code), so scripts run in the
// interpreter and nothing is written to the current directory.
//
// A script error is a longjmp to the innermost pcall frame (lua_raise); every call into the interpreter below sits in one
// (lua_pcall), so the longjmp never leaves this file's callers. A syntax error is a longjmp too, to the setjmp of parse().
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <malloc.h>
#include "context.h"
#include "node.h"
#include "astro_code_store.h"

struct luastro_option OPTION = {0};

// As in luastro's main.c.
struct ParsedChunk { NODE *body; uint32_t nlocals, nupvals, nparams; bool is_vararg; };
NODE *PARSE_lua(const char *src, const char *filename, struct ParsedChunk *out);
void  luastro_init_globals(CTX *c);
void  luastro_specialize_all(NODE *root, const char *file);
void  code_repo_add(const char *name, NODE *body, bool force);

#include "lua_tokenizer.c"
#include "lua_parser.c"
#include "lua_runtime.c"
#include "lua_stdlib.c"

#include "nfcpoly_astro_shim.h"

static CTX *G_C;                 // the one interpreter of the process (luastro's globals cannot hold two)
static int G_open;
static nfc_host_fn G_host;
static void *G_user;
static struct LuaTable *G_roots; // id -> value, reachable from the globals so that a collection keeps them
static LuaValue G_callm;         // the cfunction behind nfc_ls_call_method
static int G_nomethod;
static char **G_srcs;            // the source of every chunk: tokens and names point into it for as long as the AST lives
static size_t G_nsrcs;

// ---- the host function: __nfc_call(id, args...) --------------------------------------------------------------------
static RESULT
nfc_call(CTX *c, LuaValue *args, uint32_t argc)
{
    LuaValue out = LUAV_NIL;
    int rc;
    if (argc < 1 || !LV_IS_INT(args[0])) lua_raisef(c, "__nfc_call: missing function id");
    rc = G_host(G_user, (long)LV_AS_INT(args[0]), args + 1, argc - 1, &out);
    c->ret_info.result_cnt = 0;
    if (rc) lua_raise(c, out);
    return RESULT_OK(out);
}

// callm(target, name, args...): the method NAME of target, called with target first. Runs under lua_pcall.
static RESULT
nfc_callm(CTX *c, LuaValue *args, uint32_t argc)
{
    LuaValue target = args[0], name = args[1], f = LUAV_NIL;
    LuaValue *argv;
    uint32_t k;
    int depth;
    RESULT r;
    if (LV_IS_STR(target)) {
        LuaValue lib = lua_table_get_str(c->globals, LUASTRO_S_STRING);
        if (LV_IS_TBL(lib)) f = lua_table_get(LV_AS_TBL(lib), name);
    } else {
        LuaValue t = target;
        for (depth = 0; LV_IS_TBL(t) && depth < 100; depth++) {
            struct LuaTable *mt;
            LuaValue h;
            f = lua_table_get(LV_AS_TBL(t), name);
            if (!LV_IS_NIL(f)) break;
            mt = LV_AS_TBL(t)->metatable;
            if (!mt) break;
            h = lua_table_get_str(mt, LUASTRO_S___INDEX);
            if (LV_IS_TBL(h)) { t = h; continue; }
            if (LV_IS_CALL(h)) {
                LuaValue ia[2];
                ia[0] = t; ia[1] = name;
                f = lua_call(c, h, ia, 2);
            }
            break;
        }
    }
    if (!LV_IS_CALL(f)) { G_nomethod = 1; return RESULT_OK(LUAV_NIL); }
    argv = (LuaValue *)alloca(sizeof(LuaValue) * (argc - 1));
    argv[0] = target;
    for (k = 2; k < argc; k++) argv[k - 1] = args[k];
    c->ret_info.result_cnt = 0;
    r = lua_call(c, f, argv, argc - 1);
    return r;
}

// luastro's pcall and xpcall leave LUASTRO_CUR_UPVALS (the running closure's upvalues), the varargs and the branch state as the
// failed callee left them, so the caller of a pcall that caught an error reads its upvalues from the wrong closure (a crash for
// `local n = 0; local function f() pcall(g); n = n + 1 end`). These wrappers run the originals and put the three back when they report
// a failure. Installed over the globals by nfc_ls_open.
static void
restore_after_failure(CTX *c, RESULT r, LuaValue *va, uint32_t va_cnt, LuaValue **up)
{
    if (r != LUAV_BOOL(false)) return;
    c->varargs = va;
    c->varargs_cnt = va_cnt;
    LUASTRO_CUR_UPVALS = up;
    LUASTRO_BR = LUA_BR_NORMAL;
}

static RESULT
nfc_pcall(CTX *c, LuaValue *args, uint32_t argc)
{
    LuaValue *va = c->varargs;
    uint32_t va_cnt = c->varargs_cnt;
    LuaValue **up = LUASTRO_CUR_UPVALS;
    RESULT r = b_pcall(c, args, argc);
    restore_after_failure(c, r, va, va_cnt, up);
    return r;
}

static RESULT
nfc_xpcall(CTX *c, LuaValue *args, uint32_t argc)
{
    LuaValue *va = c->varargs;
    uint32_t va_cnt = c->varargs_cnt;
    LuaValue **up = LUASTRO_CUR_UPVALS;
    RESULT r = b_xpcall(c, args, argc);
    restore_after_failure(c, r, va, va_cnt, up);
    return r;
}

// ---- running ------------------------------------------------------------------------------------------------------
// lua_pcall without its multiple-result protocol: a chunk's `return e` leaves the result count of an earlier call in ret_info, which
// lua_pcall would take for extra results; lua_call's own return value is the first one. 0 ok (*out the first result), 2 error
// (*out its value). The interpreter's globals that a longjmp skips are put back.
static int
protected_call(LuaValue fn, LuaValue *args, uint32_t argc, LuaValue *out)
{
    CTX *c = G_C;
    struct lua_pcall_frame frame;
    LuaValue *va = c->varargs;
    uint32_t va_cnt = c->varargs_cnt;
    LuaValue **up = LUASTRO_CUR_UPVALS;
    frame.prev = c->pcall_top;
    frame.sp_save = c->sp;
    c->pcall_top = &frame;
    if (setjmp(frame.jb) == 0) {
        c->ret_info.result_cnt = 0;
        *out = lua_call(c, fn, args, argc);
        c->pcall_top = frame.prev;
        return 0;
    }
    c->pcall_top = frame.prev;
    c->sp = frame.sp_save;
    c->varargs = va;
    c->varargs_cnt = va_cnt;
    LUASTRO_CUR_UPVALS = up;
    LUASTRO_BR = LUA_BR_NORMAL;
    *out = c->last_error;
    return 2;
}

// Parses SRC (NUL-terminated, kept for good). 0 ok, 1 syntax error with the message in ERR.
static int
parse(const char *src, struct ParsedChunk *pc, char *err, size_t errcap)
{
    jmp_buf jb;
    if (setjmp(jb) == 0) {
        lua_tok_error_jmp_set(&jb, 1);
        PARSE_lua(src, "=snippet", pc);
        lua_tok_error_jmp_set(NULL, 0);
        return 0;
    }
    lua_tok_error_jmp_set(NULL, 0);
    snprintf(err, errcap, "%s", L_err_msg);
    return 1;
}

static char *
keep_source(const char *prefix, const char *src, size_t len)
{
    size_t pl = strlen(prefix);
    char *buf = (char *)malloc(pl + len + 2);
    G_srcs = (char **)realloc(G_srcs, (G_nsrcs + 1) * sizeof(char *));
    G_srcs[G_nsrcs++] = buf;
    memcpy(buf, prefix, pl);
    memcpy(buf + pl, src, len);
    buf[pl + len] = '\n';   // a final -- comment ends
    buf[pl + len + 1] = '\0';
    return buf;
}

int
nfc_ls_eval(const char *src, size_t len, nfc_lv *out)
{
    struct ParsedChunk pc;
    char err[256];
    struct LuaClosure *cl;
    /* A source that is a single expression returns its value: try it as `return <src>` first, then as statements. */
    if (parse(keep_source("return ", src, len), &pc, err, sizeof(err)) != 0 &&
        parse(keep_source("", src, len), &pc, err, sizeof(err)) != 0) {
        *out = LUAV_STR(lua_str_intern(err));
        return 1;
    }
    cl = lua_closure_new(pc.body, pc.nparams, pc.nlocals, pc.nupvals, pc.is_vararg, "<chunk>");
    return protected_call(LUAV_FUNC(cl), NULL, 0, out);
}

int
nfc_ls_call(nfc_lv f, const nfc_lv *args, unsigned argc, nfc_lv *out)
{
    return protected_call(f, (LuaValue *)args, argc, out);
}

int
nfc_ls_call_method(nfc_lv target, const char *name, size_t nlen, const nfc_lv *args, unsigned argc, nfc_lv *out)
{
    LuaValue *argv = (LuaValue *)malloc(sizeof(LuaValue) * (argc + 2));
    unsigned k;
    int rc;
    argv[0] = target;
    argv[1] = LUAV_STR(lua_str_intern_n(name, nlen));
    for (k = 0; k < argc; k++) argv[k + 2] = args[k];
    G_nomethod = 0;
    rc = protected_call(G_callm, argv, argc + 2, out);
    free(argv);
    if (rc == 0 && G_nomethod) return 3;
    return rc;
}

// ---- opening and closing -------------------------------------------------------------------------------------------
int
nfc_ls_open(nfc_host_fn fn, void *user)
{
    if (G_open) return -1;
    OPTION.no_compiled_code = true;
    OPTION.quiet = true;
    if (!G_C) {
        G_C = luastro_create_context();
    } else {
        /* A second interpreter in this process: the old one's globals are dropped, the string pool and the object list stay. */
        G_C->globals = lua_table_new(0, 32);
        G_C->sp = G_C->stack;
        G_C->pcall_top = NULL;
        G_C->last_error = LUAV_NIL;
        G_C->varargs = NULL;
        G_C->varargs_cnt = 0;
        G_C->ret_info.result_cnt = 0;
        LUASTRO_CUR_UPVALS = NULL;
        LUASTRO_BR = LUA_BR_NORMAL;
    }
    luastro_init_globals(G_C);
    /* No files, no process exit, no clock or environment unless the host binds them. */
    lua_table_set_str(G_C->globals, lua_str_intern("io"), LUAV_NIL);
    lua_table_set_str(G_C->globals, lua_str_intern("os"), LUAV_NIL);
    G_host = fn;
    G_user = user;
    G_roots = lua_table_new(0, 16);
    lua_table_set_str(G_C->globals, lua_str_intern("\001nfcpoly.roots"), LUAV_TABLE(G_roots));
    G_callm = LUAV_CFUNC(lua_cfunc_new("callm", nfc_callm));
    lua_table_set_str(G_C->globals, lua_str_intern("\001nfcpoly.callm"), G_callm);
    lua_table_set_str(G_C->globals, lua_str_intern("pcall"), LUAV_CFUNC(lua_cfunc_new("pcall", nfc_pcall)));
    lua_table_set_str(G_C->globals, lua_str_intern("xpcall"), LUAV_CFUNC(lua_cfunc_new("xpcall", nfc_xpcall)));
    lua_table_set_str(G_C->globals, lua_str_intern("__nfc_call"), LUAV_CFUNC(lua_cfunc_new("__nfc_call", nfc_call)));
    G_open = 1;
    return 0;
}

void
nfc_ls_close(void)
{
    size_t k;
    if (!G_open) return;
    G_open = 0;
    G_host = NULL;
    G_user = NULL;
    G_roots = NULL;
    for (k = 0; k < G_nsrcs; k++) free(G_srcs[k]);
    free(G_srcs);
    G_srcs = NULL;
    G_nsrcs = 0;
}

// ---- values -------------------------------------------------------------------------------------------------------
int
nfc_ls_kind(nfc_lv v)
{
    if (LV_IS_NIL(v)) return NFC_NIL;
    if (LV_IS_BOOL(v)) return NFC_BOOL;
    if (LV_IS_INT(v)) return NFC_INT;
    if (LV_IS_FLOAT(v)) return NFC_FLOAT;
    if (LV_IS_STR(v)) return NFC_STR;
    if (LV_IS_TBL(v)) return NFC_TABLE;
    if (LV_IS_FN(v) || LV_IS_CF(v)) return NFC_FUNC;
    if (LV_IS_THREAD(v)) return NFC_THREAD;
    return NFC_OTHER;
}

int nfc_ls_int_fits(long long i) { return i >= -(1LL << 62) && i < (1LL << 62); }
nfc_lv nfc_ls_mk_bool(int b) { return LUAV_BOOL(b); }
nfc_lv nfc_ls_mk_int(long long i) { return LUAV_INT(i); }
nfc_lv nfc_ls_mk_float(double d) { return LUAV_FLOAT(d); }
nfc_lv nfc_ls_mk_str(const char *s, size_t n) { return LUAV_STR(lua_str_intern_n(s, n)); }
nfc_lv nfc_ls_mk_table(unsigned narr, unsigned nhash) { return LUAV_TABLE(lua_table_new(narr, nhash)); }
int nfc_ls_as_bool(nfc_lv v) { return LV_AS_BOOL(v); }
long long nfc_ls_as_int(nfc_lv v) { return LV_AS_INT(v); }
double nfc_ls_as_float(nfc_lv v) { return LV_AS_FLOAT(v); }
const char *nfc_ls_str_data(nfc_lv v) { return LV_AS_STR(v)->data; }
size_t nfc_ls_str_len(nfc_lv v) { return LV_AS_STR(v)->len; }
nfc_lv nfc_ls_tostring(nfc_lv v) { return lua_tostring(G_C, v); }

void nfc_ls_table_seti(nfc_lv t, long long i, nfc_lv v) { lua_table_seti(LV_AS_TBL(t), i, v); }
nfc_lv nfc_ls_table_geti(nfc_lv t, long long i) { return lua_table_geti(LV_AS_TBL(t), i); }
void nfc_ls_table_set_str(nfc_lv t, const char *name, nfc_lv v) { lua_table_set_str(LV_AS_TBL(t), lua_str_intern(name), v); }
nfc_lv nfc_ls_table_get_str(nfc_lv t, const char *name) { return lua_table_get_str(LV_AS_TBL(t), lua_str_intern(name)); }
long long nfc_ls_table_len(nfc_lv t) { return lua_table_len(LV_AS_TBL(t)); }
int nfc_ls_table_next(nfc_lv t, nfc_lv *k, nfc_lv *v) { return lua_table_next(LV_AS_TBL(t), k, v); }

int
nfc_ls_table_is_array(nfc_lv t)
{
    long long n = lua_table_len(LV_AS_TBL(t)), count = 0;
    LuaValue k = LUAV_NIL, v;
    while (lua_table_next(LV_AS_TBL(t), &k, &v)) {
        if (!LV_IS_INT(k) || LV_AS_INT(k) < 1 || LV_AS_INT(k) > n) return 0;
        count++;
    }
    return count == n;
}

void nfc_ls_set_global(const char *name, nfc_lv v) { lua_table_set_str(G_C->globals, lua_str_intern(name), v); }
nfc_lv nfc_ls_get_global(const char *name) { return lua_table_get_str(G_C->globals, lua_str_intern(name)); }
void nfc_ls_root_set(long id, nfc_lv v) { lua_table_seti(G_roots, id, v); }
nfc_lv nfc_ls_root_get(long id) { return lua_table_geti(G_roots, id); }
void nfc_ls_collect(void) { luastro_gc_collect(G_C); }
